if "CurrentMsg" == "EclipseMsg":
    from . import _CurrentMsgPayload as _m
    from Basilisk.utilities import deprecated

# ----- __init__ alias: accept illuminationFactor as synonym for shadowFactor -----
    _orig_init = CurrentMsgPayload.__init__

    def _init_with_alias(self, *, illuminationFactor=..., shadowFactor=..., **kwargs):
        if shadowFactor is not ...:
            deprecated.deprecationWarn(
                "EclipseMsgPayload(shadowFactor=...)",
                "2026/12/31",
                "Use EclipseMsgPayload(illuminationFactor=...) instead.",
            )
            illuminationFactor = shadowFactor
        _orig_init(self, **kwargs)
        if illuminationFactor is not ...:
            _m.CurrentMsgPayload_shadowFactor_set(self, illuminationFactor)

    CurrentMsgPayload.__init__ = _init_with_alias

# ----- Payload aliasing -----
    def _get_illum(self):
        return _m.CurrentMsgPayload_shadowFactor_get(self)

    def _set_illum(self, v):
        _m.CurrentMsgPayload_shadowFactor_set(self, v)

    CurrentMsgPayload.illuminationFactor = property(_get_illum, _set_illum)

# Deprecate the old shadowFactor name
    def _warn_get_shadow(self):
        deprecated.deprecationWarn(
            "EclipseMsgPayload.shadowFactor",
            "2026/12/31",
            "Use EclipseMsgPayload.illuminationFactor instead (0=fully eclipsed, 1=fully sunlit)."
        )
        return _m.CurrentMsgPayload_shadowFactor_get(self)

    def _warn_set_shadow(self, v):
        deprecated.deprecationWarn(
            "EclipseMsgPayload.shadowFactor",
            "2026/12/31",
            "Use EclipseMsgPayload.illuminationFactor instead (0=fully eclipsed, 1=fully sunlit)."
        )
        _m.CurrentMsgPayload_shadowFactor_set(self, v)

    CurrentMsgPayload.shadowFactor = property(_warn_get_shadow, _warn_set_shadow)

# ----- Recorder aliasing so logs can use illuminationFactor -----
    try:
        _orig_rec_getattr = EclipseMsgRecorder.__getattr__

        def _rec_getattr_with_alias(self, name):
            if name == "illuminationFactor":
# Delegate to the original implementation but ask for shadowFactor
                return _orig_rec_getattr(self, "shadowFactor")
            return _orig_rec_getattr(self, name)

        EclipseMsgRecorder.__getattr__ = _rec_getattr_with_alias
    except Exception:
        pass


# Freeze the payload data struct so that assigning a field name that does not
# already exist raises instead of silently succeeding (issue #305). Only the
# CurrentMsgPayload data class is protected: the Msg/Reader/Recorder/Writer and the
# std::vector wrapper classes are intentionally left untouched, because their
# custom __getattr__ has side effects that protectSetAttr's hasattr() probe would
# trigger on partially constructed objects (e.g. a Recorder mid-construction).
CurrentMsgPayload.__setattr__ = protectSetAttr

class CurrentMsg_C(object):
    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")
    __repr__ = _swig_repr
    header = property(_CurrentMsgPayload.CurrentMsg_C_header_get, _CurrentMsgPayload.CurrentMsg_C_header_set)
    payload = property(_CurrentMsgPayload.CurrentMsg_C_payload_get, _CurrentMsgPayload.CurrentMsg_C_payload_set)
    payloadPointer = property(_CurrentMsgPayload.CurrentMsg_C_payloadPointer_get, _CurrentMsgPayload.CurrentMsg_C_payloadPointer_set)
    headerPointer = property(_CurrentMsgPayload.CurrentMsg_C_headerPointer_get, _CurrentMsgPayload.CurrentMsg_C_headerPointer_set)

    def _recorder(self, timeDiff=0):
        return _CurrentMsgPayload.CurrentMsg_C__recorder(self, timeDiff)


    def recorder(self, timeDiff=0):
        """Create a recorder that keeps this C message's storage owner alive."""
        from Basilisk.architecture.messaging import _msgKeepAlive
        recorder = self._recorder(timeDiff)
        _msgKeepAlive.retainRecorderSource(recorder, self)
        return recorder

    def subscribeTo(self, source):
        """subscribe to another message source"""
        from Basilisk.architecture.messaging import _msgKeepAlive
        if type(source) == type(self):
            CurrentMsg_C_subscribe(self, source)
        elif type(source) == CurrentMsg:
            CurrentMsg_cpp_subscribe(self, source)
        elif type(source) == int: #Note that is assumes it is a uint64_t address in memory
            CurrentMsg_addr_subscribe(self, source)
            _msgKeepAlive.releaseSource(self)
            return  # a raw address: the caller owns the source, nothing to keep alive
        else:
            raise Exception('tried to subscribe CurrentMsg to another message type')
    # issue #1433: this Msg_C reader now holds raw pointers into `source`; keep the
    # (otherwise garbage-collectable) source object alive for as long as we read it
        _msgKeepAlive.retainSource(self, source)

    def unsubscribe(self):
        """Unsubscribe to the connected message, noop if no message was connected"""
        from Basilisk.architecture.messaging import _msgKeepAlive
        CurrentMsg_unsubscribe(self)
    # Clear the native pointers before releasing the source. Source destruction
    # can invoke Python weakref callbacks that re-enter this reader.
        _msgKeepAlive.releaseSource(self)

    def isSubscribedTo(self, source):
        """check if self is subscribed to another message source"""
        if type(source) == type(self):
            return (CurrentMsg_C_isSubscribedTo(self, source))
        elif type(source) == CurrentMsg:
            return (CurrentMsg_cpp_isSubscribedTo(self, source))
        elif type(source) == int: #Note that this assumes it is a uint64_t address location in memory
            return (CurrentMsg_cpp_isSubscribedToAddr(self, source))
        else:
            return 0


    def init(self, data=None):
        """returns a Msg copy connected to itself"""
        CurrentMsg_C_addAuthor(self, self)
        if data:
            CurrentMsg_C_write(data, self, -1, 0)
        return self

    def write(self, payload, time=0, moduleID=0):
        """write the message payload.
        The 2nd argument is time in nanoseconds.  It is optional and defaults to 0.
        The 3rd argument is the module ID which defaults to 0.
        """
        CurrentMsg_C_addAuthor(self, self)
        CurrentMsg_C_write(payload, self, moduleID, time)  # msgs written in Python have 0 module ID
        return self

    def read(self):
        """read the message payload."""
        return CurrentMsg_C_read(self)


    def __init__(self):
        _CurrentMsgPayload.CurrentMsg_C_swiginit(self, _CurrentMsgPayload.new_CurrentMsg_C())
    __swig_destroy__ = _CurrentMsgPayload.delete_CurrentMsg_C

